const $ = s => document.querySelector(s);
const form = $('#form');
const grades = ['새것 같음', '양호', '사용감 있음'];
const storageKey = 'dasi-ipda-v1';
let photos = [], busy = false, typeFilter = '전체', own = [];
try { own = JSON.parse(localStorage.getItem(storageKey) || '[]'); if (!Array.isArray(own)) own = []; } catch { own = []; }
const samples = [
  {id:'s1',title:'포근한 크림 라운드 니트',size:'M',age:'성인',grade:'양호',type:'판매',price:12000,color:'#e8dfcb',bg:'#ebece5',shape:'top'},
  {id:'s2',title:'매일 입기 좋은 데님 팬츠',size:'S',age:'청소년',grade:'양호',type:'판매',price:8000,color:'#7793a5',bg:'#e8edf0',shape:'pants'},
  {id:'s3',title:'쑥쑥 자라는 아이의 줄무늬 티',size:'120',age:'아동',grade:'사용감 있음',type:'나눔',price:0,color:'#b4bd9e',bg:'#eef0e7',shape:'top'}
];
function el(tag, cls, text) { const n = document.createElement(tag); if(cls) n.className=cls; if(text!==undefined) n.textContent=text; return n; }
function garment(item) {
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 260 260');svg.setAttribute('aria-hidden','true');
  svg.innerHTML=item.shape==='pants' ? `<path d="M70 30h120l-5 205h-47l-9-130-10 130H72z" fill="${item.color}"/><path d="M70 54h119M130 32v69M82 65q20 0 24-17m71 17q-20 0-24-17" fill="none" stroke="#ffffff60" stroke-width="3"/>` : `<path d="M91 35l-43 19-32 62 35 21 28-41-4 139h112l-6-139 28 41 35-21-32-62-43-19q-39 23-78 0z" fill="${item.color}"/><path d="M91 35q39 46 78 0M76 217h110M48 119l-24-14m188 14 24-14" fill="none" stroke="#ffffff80" stroke-width="6"/>`;
  return svg;
}
function visual(item) {const v=el('div','visual');v.style.background=item.bg||'#edf0e8';if(item.photos?.length){const img=el('img');img.src=item.photos[0].data;img.alt=item.title;v.append(img);}else v.append(garment(item));v.append(el('span','badge',item.sample?'예시 상품':'시연 검수 완료'));return v;}
function render() {
  const term=$('#search').value.trim().toLowerCase();const age=$('#ageFilter').value;
  const items=[...own,...samples.map(x=>({...x,sample:true}))].filter(x=>(typeFilter==='전체'||x.type===typeFilter)&&(!age||x.age===age)&&(!term||`${x.title} ${x.size} ${x.description||''}`.toLowerCase().includes(term)));
  $('#cards').replaceChildren();$('#count').textContent=`${items.length}개의 옷`;$('#empty').hidden=!!items.length;
  for(const item of items){const c=el('button','card');c.type='button';c.append(visual(item),el('h3','',item.title));const meta=el('p','meta');meta.append(el('span','',`${item.age} · ${item.size}`),el('span','badge',item.grade));c.append(meta,el('p','price',item.type==='나눔'?'무료 나눔':`${Number(item.price).toLocaleString('ko-KR')}원`));c.addEventListener('click',()=>detail(item));$('#cards').append(c);}
}
function detail(item){const b=$('#detailBody');b.replaceChildren();if(item.photos?.length){const gallery=el('div','detail-images');for(const p of item.photos){const img=el('img');img.src=p.data;img.alt='등록된 옷 사진';gallery.append(img);}b.append(gallery);}else b.append(visual(item));b.append(el('h2','',item.title),el('p','badge',`${item.grade} · ${item.age} · ${item.size}`),el('h2','',item.type==='나눔'?'무료 나눔':`${Number(item.price).toLocaleString('ko-KR')}원`),el('p','detail-description',item.description||'화면 구성을 보여주는 예시 상품입니다.'),el('p','guide',item.sample?'예시 상품으로 실제 거래할 수 없습니다.':'시연 검수를 거친 글입니다. 실제 AI 분석 및 구매·채팅 기능은 제공하지 않습니다. 이 브라우저에서만 볼 수 있습니다.'));
  if(!item.sample){const del=el('button','delete','내 게시글 삭제');del.onclick=()=>{const next=own.filter(x=>x.id!==item.id);try{localStorage.setItem(storageKey,JSON.stringify(next));own=next;$('#detail').close();render();}catch{toast('저장소에 접근하지 못했어요. 브라우저 설정을 확인해주세요.');}};b.append(del);}$('#detail').showModal();}
function page(editor){$('#browse').hidden=editor;$('#editor').hidden=!editor;window.scrollTo(0,0);}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500);}
function invalidate(){ $('#reviewResult').replaceChildren(); }
function previews(){const box=$('#previews');box.replaceChildren();photos.forEach((p,i)=>{const d=el('div','preview');const img=el('img');img.src=p.data;img.alt=`옷 사진 ${i+1}`;const remove=el('button','','×');remove.type='button';remove.setAttribute('aria-label',`사진 ${i+1} 삭제`);remove.onclick=()=>{photos.splice(i,1);previews();invalidate();};d.append(img,remove,el('small','',`${p.width} × ${p.height}`));box.append(d);});}
function readPhoto(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{try{const scale=Math.min(1,1000/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve({data:canvas.toDataURL('image/jpeg',.76),width:img.naturalWidth,height:img.naturalHeight});}catch{reject();}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject();};img.src=url;});}
$('#photos').onchange=async e=>{if(busy)return;busy=true;$('#submit').disabled=true;$('#photos').disabled=true;const errors=[];for(const file of e.target.files){if(photos.length>=8){errors.push('사진은 최대 8장까지 올릴 수 있어요.');break;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){errors.push('10MB 이하 JPG, PNG, WebP 파일을 선택해주세요.');continue;}try{photos.push(await readPhoto(file));}catch{errors.push('사진을 읽을 수 없어요. 다른 파일을 선택해주세요.');}}$('#photoError').textContent=[...new Set(errors)].join(' ');e.target.value='';previews();invalidate();busy=false;$('#submit').disabled=false;$('#photos').disabled=false;};
function result(message,warning=true){const n=el('p',`result${warning?' warn':''}`,message);$('#reviewResult').replaceChildren(n);}
function verify(pics,scenario){if(pics.length<3)return '사진이 부족해요. 앞면·뒷면·라벨이 보이도록 최소 3장을 올려주세요.';if(pics.some(p=>Math.min(p.width,p.height)<600))return '작은 사진이 있어요. 해당 사진을 삭제하고 가로·세로 모두 600px 이상인 사진으로 다시 올려주세요.';if(scenario==='detail')return '추가 촬영 요청 시연: 소매 끝과 얼룩 부위를 가까이 촬영해주세요. 사진을 추가한 후 시연 조건을 “상태 등급 일치”로 변경해 다시 확인하세요.';if(scenario==='mismatch')return '등급 불일치 시연: 얼룩이나 보풀로 등급 조정이 필요한 상황입니다. 등급을 다시 선택한 후 시연 조건을 “상태 등급 일치”로 변경해주세요.';return null;}
form.onsubmit=e=>{e.preventDefault();if(busy)return;const data=new FormData(form);const title=data.get('title').trim(),size=data.get('size').trim(),description=data.get('description').trim();if(!title||!size||!description){result('제목, 사이즈, 설명을 공백 없이 입력해주세요.');return;}const issue=verify(photos,data.get('scenario'));if(issue){result(issue);return;}const item={id:crypto.randomUUID(),title,size,description,age:data.get('age'),grade:data.get('grade'),type:data.get('type'),price:data.get('type')==='나눔'?0:Number(data.get('price')),photos:photos.map(p=>({...p}))};const next=[item,...own];try{localStorage.setItem(storageKey,JSON.stringify(next));own=next;}catch{result('브라우저 저장 공간이 부족하거나 저장이 차단됐어요. 기존 글을 삭제하거나 사진 수를 줄이고 다시 시도해주세요.');return;}form.reset();photos=[];previews();invalidate();$('#photoError').textContent='';syncPrice();typeFilter='전체';document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('selected',c.dataset.type==='전체'));$('#search').value='';$('#ageFilter').value='';render();page(false);toast('시연 검수 완료! 내 브라우저에 게시글을 등록했어요.');};
function syncPrice(){const free=form.elements.type.value==='나눔';form.elements.price.disabled=free;form.elements.price.required=!free;if(free)form.elements.price.value=0;else if(form.elements.price.value==='0')form.elements.price.value='';}
form.elements.type.onchange=syncPrice;form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);
$('#write').onclick=$('#heroWrite').onclick=()=>page(true);$('#back').onclick=$('#home').onclick=()=>page(false);document.querySelectorAll('a.brand').forEach(a=>a.onclick=e=>{e.preventDefault();page(false);});$('#search').oninput=render;$('#ageFilter').onchange=render;document.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{typeFilter=c.dataset.type;document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('selected',x===c));render();});$('#closeDetail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});render();
